import{_ as p,r as s,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"使用 Laravel 包 - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":3,"title":"配置文件","slug":"配置文件","link":"#配置文件","children":[]},{"level":3,"title":"别名和服务提供者","slug":"别名和服务提供者","link":"#别名和服务提供者","children":[]},{"level":3,"title":"迁移和模型","slug":"迁移和模型","link":"#迁移和模型","children":[]}],"relativePath":"3.x/zh-cn/extend/resources/using-laravel-packages.md","filePath":"3.x/zh-cn/extend/resources/using-laravel-packages.md"}'),r={name:"3.x/zh-cn/extend/resources/using-laravel-packages.md"};function u(k,n,g,d,f,h){const e=s("pre-heading"),t=s("post-heading");return o(),c("div",null,[a(e),n[0]||(n[0]=l("h1",null,"使用 Laravel 包",-1)),a(t),n[1]||(n[1]=i(`<p>在 October CMS 插件中引入 Laravel 包时，有一些注意事项需要了解。</p><h3 id="配置文件"><a href="#配置文件" class="header-anchor">#</a> 配置文件</h3><p>Laravel 包通常会提供配置文件，您应将此配置复制到您的插件目录中。例如，如果文件名为 <strong>purifier.php</strong> 并包含一些基本配置值。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">return</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;encoding&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;UTF-8&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;finalize&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;cachePath&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">storage_path</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;app/purifier&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;cacheFileMode&#39;</span> <span class="token operator">=&gt;</span> <span class="token number">0755</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">;</span>
</code></pre></div><p>将此文件复制到您的插件目录，例如 <strong>plugins/acme/blog/config/purifier.php</strong>。重要的是要复制和维护整个文件，因为任何缺失的键都不会从基础配置中继承。</p><p>接下来，您应在 <code>boot()</code> 方法中将插件配置的内容传递给包配置。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">boot</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">set</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;purifier&#39;</span><span class="token punctuation">,</span> <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::purifier&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>这将把所有包配置值设置为您的插件配置值。以下值将相等。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;purifier.encoding&#39;</span><span class="token punctuation">)</span> <span class="token operator">===</span> <span class="token class-name static-context">Config</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog::purifier.encoding&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>现在您可以像使用常规插件配置值和<a href="./../settings/file-settings.html">标准配置方法</a>一样提供包的配置值。</p><h3 id="别名和服务提供者"><a href="#别名和服务提供者" class="header-anchor">#</a> 别名和服务提供者</h3><p>如果 Laravel 包包含任何服务提供者和别名，您应在插件的 <code>register()</code> 方法中使用 <code>App</code> 门面手动注册它们。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">register</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Register the aliases provided by the packages used by your plugin</span>
    <span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">registerClassAlias</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Purifier&#39;</span><span class="token punctuation">,</span> <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Mews<span class="token punctuation">\\</span>Purifier<span class="token punctuation">\\</span>Facades<span class="token punctuation">\\</span>Purifier</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Register the service providers provided by the packages used by your plugin</span>
    <span class="token class-name static-context">App</span><span class="token operator">::</span><span class="token function">register</span><span class="token punctuation">(</span><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Mews<span class="token punctuation">\\</span>Purifier<span class="token punctuation">\\</span>PurifierServiceProvider</span><span class="token operator">::</span><span class="token keyword">class</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="迁移和模型"><a href="#迁移和模型" class="header-anchor">#</a> 迁移和模型</h3><p>与数据库交互的 Laravel 包通常会包含自己的数据库迁移和 Eloquent 模型。您应将这些迁移和模型复制到您的插件目录中。</p><p>请确保将 Model 类更改为扩展基础 <code>October\\Rain\\Database\\Model</code> 类，而不是基础 Laravel Eloquent 模型类，以利用 October CMS 中的扩展技术特性。</p><p>重命名数据库表并以您的作者代码和插件名称作为前缀也是一个好做法。例如，名为 <code>posts</code> 的表应重命名为 <code>rainlab_blog_posts</code>。</p>`,17))])}const _=p(r,[["render",u]]);export{v as __pageData,_ as default};
